head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDBNS25300.xml";
scwin.processGp;
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vs_G_Std_Cd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 설명       : 보증기관조회
 ***********************************************/
scwin.fn_list_search = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_SRCH_LIST";
    url += "&queryId=lds.stf.bnslistsrchl.select.instlist";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_NM=" + txb_com_abbrv.getValue(); // 
    url += "&{P}V_INST_STAT_CD=" + $c.stf.getObjectValue(cmb_sch_stat_cd); // 

    dts_List_1.DataID = encodeURI(url);
    dts_List_1.Reset();
    $c.cm.ShowWin(grd_List1);
    return url;
};


/********************************************** 
 * 설명       : 보증기관 상세조회
 ***********************************************/
scwin.fn_searchDetail = function(row) {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_SRCH_LIST_DETAIL";
    url += "&queryId=lds.stf.bnslistsrchl.select.instlistdetail";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_CD=" + dts_List_1.getCellData(row, "BND_INST_CD"); // 			

    dts_List_2.DataID = encodeURI(url);
    dts_List_2.Reset();
    $c.cm.ShowWin(grd_List2);
    return url;
};


/********************************************** 
 * 함수명   : fn_GetParInst
 * 설명       : 기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParInst = function(arrPar) {
    arrPar[0] = {
        INST_CD: $c.stf.getObjectValue(txb_isur_cd),
        INST_NM: $c.stf.getObjectValue(txb_com_abbrv),
        LBL_NM: '',
        INIT_TP_CD: "2"
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParInst
 * 설명       : 기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParInst = function(arrPar) {
    if (typeof(arrPar[0].INST_CD) != 'undefined') {
        txb_isur_cd.setValue(arrPar[0].INST_CD);
        txb_com_abbrv.setValue(arrPar[0].INST_NM);
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: scwin.vs_G_Std_Cd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.gform_onload = function() {
    /********************************************** 
     * 함수명   : gform > onload
     * 설명      : 화면 Onload
     ***********************************************/
    $c.bns.BnsPanelToGroupBox(panel_Top);
};
scwin.btn_Search_onclick = function() {
    /********************************************** 
     * Event   : btn_Search > OnClick
     * 설명    : 조회버튼 클릭
     ***********************************************/
    // 조회
    scwin.fn_list_search();
};
scwin.img_com_srch_onclick = function() {
    /********************************************** 
     * Event   : img_com_srch > OnClick
     * 설명    : 발행기관 조회팝업
     ***********************************************/
    scwin.fn_GetPar = fn_GetParInst;
    scwin.fn_SetPar = fn_SetParInst;
    $c.bns.fn_PopInstSearch(img_com_srch);
};
scwin.txb_isur_cd_onblur = function() {
    /********************************************** 
     * 함수명   : txb_ISUR_CD > onblur
     * 설명      : 발행기관 코드 변경
     ***********************************************/
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.dts_List_1_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_List_1 > OnLoadError
     * 설명    : dts_List_1 조회에러시 처리
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * Event   : dts_List_1 > OnLoadCompleted
     * 설명    : dts_List_1 조회성공시 처리
     ***********************************************/
    dts_List_1.setRowPosition(0, 0);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page1);
    $c.cm.CloseWin(rowcount, grd_List1);
};
scwin.dts_List_2_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_List_2 > OnLoadError
     * 설명    : dts_List_2 조회에러시 처리
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * Event   : dts_List_2 > OnLoadCompleted
     * 설명    : dts_List_2 조회성공시 처리
     ***********************************************/
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page2);
    $c.cm.CloseWin(rowcount, grd_List2);
};
scwin.dts_List_1_OnRowPosChanged = function(row) {
    /********************************************** 
     * Event   : dts_List_1 > OnRowPosChanged
     * 설명    : 그리드 위치 변경시 세팅
     ***********************************************/
    if (row == 0) return;
    scwin.fn_searchDetail(row);
};
scwin.btn_Excel_onclick = function() {
    /********************************************** 
     * Event   : btn_Excel > onclick
     * 설명    : 엑셀버튼클릭
     ***********************************************/
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_보증기관조회.xls";
    $c.data.downloadGridViewExcel(grd_List2, "보증기관조회", "", "8");
};
scwin.grd_List2_OnDblClick = function(row, colid) {
    /********************************************** 
     * Event   : grd_List2 > OnDblClick
     * 설명    : 종목그리드 더블클릭시 상세정보 팝업 호출
     ***********************************************/
    if (row == 0) return;
    scwin.vs_G_Std_Cd = dts_List_2.getCellData(row, "STD_CD");
    scwin.fn_GetPar = fn_GetParIsuDelInfo;
    $c.bns.fn_PopIsuDetail(grd_List1);
};
